/**
 * Media helpers (client-side).
 *
 * IMAGES  -> Cloudinary (URLs are built with on-the-fly transformations so the
 *            CDN resizes/compresses per device — responsive delivery).
 * VIDEOS  -> Mux (thumbnails are generated by Mux's image API from playback id).
 * PRIVATE -> Convex file storage (never public CDN URLs).
 */

const CLOUDY_IMG = "/image/upload/";

/**
 * Return an optimized/responsive Cloudinary URL for the given secure URL.
 * Injects f_auto,q_auto + optional width so the CDN serves the right size and
 * format for every device. Returns the original URL when it is not a
 * Cloudinary image URL.
 */
export function optimizedImg(
  src: string | null | undefined,
  opts: { w?: number; h?: number; q?: number; crop?: "fill" | "scale" | "limit" } = {},
): string | null {
  if (!src) return null;
  const idx = src.indexOf(CLOUDY_IMG);
  if (idx === -1) return src;

  const parts: string[] = ["f_auto", "q_auto"];
  if (opts.w) parts.push(`w_${opts.w}`);
  if (opts.h) parts.push(`h_${opts.h}`);
  if (opts.q) parts.push(`q_${opts.q}`);
  if (opts.crop && opts.w && opts.h) parts.push(`c_${opts.crop}`);

  return `${src.slice(0, idx)}${CLOUDY_IMG}${parts.join(",")}/${src.slice(idx + CLOUDY_IMG.length)}`;
}

/** Mux-generated video thumbnail (images generated from the course video). */
export function muxThumb(
  playbackId: string | null | undefined,
  opts: { width?: number; time?: number } = {},
): string | null {
  if (!playbackId) return null;
  const q = new URLSearchParams();
  q.set("time", String(opts.time ?? 1));
  q.set("width", String(opts.width ?? 640));
  return `https://image.mux.com/${playbackId}/thumbnail.jpg?${q.toString()}`;
}

/** Human-friendly byte size, e.g. 4.2 MB. */
export function formatBytes(bytes?: number | null): string {
  if (!bytes || bytes <= 0) return "—";
  const units = ["B", "KB", "MB", "GB"];
  let i = 0;
  let n = bytes;
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024;
    i += 1;
  }
  return `${n.toFixed(n >= 10 || i === 0 ? 0 : 1)} ${units[i]}`;
}
